toad_implementation.code_blueprint:
canvas {
  size: 800px 800px;
  fill: #0B001A;
  font-family: "VT323, monospace";
}

>deepViolet = #0B001A;
>hotPink = #FF007F;
>laserCyan = #00FFFF;
>sunOrange = #FFAA00;

circle #synthSun {
  at: center of canvas offset 0px -40px;
  size: 280px;
  fill: >sunOrange;
}

rect #sunStripe1 {
  at: center of #synthSun offset 0px 20px;
  size: 280px 8px;
  fill: >deepViolet;
}

rect #sunStripe2 {
  at: center of #synthSun offset 0px 50px;
  size: 280px 14px;
  fill: >deepViolet;
}

rect #sunStripe3 {
  at: center of #synthSun offset 0px 90px;
  size: 280px 22px;
  fill: >deepViolet;
}

rect #gridFloor {
  at: bottom left of canvas;
  size: 800px 300px;
  fill: #120324;
  stroke: >laserCyan;
  stroke-width: 2px;
}

text #arcadeTitle {
  at: top center of canvas offset 0px 60px;
  content: "N E O N   O U T R U N";
  font-size: 48px;
  font-weight: 700;
  color: >hotPink;
}

text #scoreBoard {
  at: below #arcadeTitle offset 8px;
  content: "1 PLAYER  •  HIGH SCORE: 994,200";
  font-size: 20px;
  color: >laserCyan;
}
